#!/usr/bin/env bash
# Regenerates agent-session-big.json: dozens of real MCP tool schemas (GitHub's, once per
# org), a project system prompt and retrieved knowledge, because a one-tool fixture cannot
# catch a model that stops calling tools once the prompt is large (llama.cpp #26530).
#
# Usage: tests/fixtures/make-big-session.sh   (needs docker and jq)
set -euo pipefail
cd "$(dirname "$0")/../.."

IMAGE=ghcr.io/github/github-mcp-server:v1.14.0
TOOLS=search_repositories,search_code,get_file_contents,get_repository_tree,list_commits,search_pull_requests,pull_request_read,actions_list,get_job_logs,list_dependabot_alerts,list_code_scanning_alerts,list_repository_collaborators,get_team_members
ORGS='["cloudwalksolutions","boatload-llc","twofit-corp"]'
OUT=tests/fixtures/agent-session-big.json

schemas=$(
    {
        echo '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"fixture","version":"1"}}}'
        echo '{"jsonrpc":"2.0","method":"notifications/initialized"}'
        echo '{"jsonrpc":"2.0","id":2,"method":"tools/list"}'
        sleep 3
    } | docker run -i --rm -e GITHUB_PERSONAL_ACCESS_TOKEN=unused -e GITHUB_READ_ONLY=true \
            -e GITHUB_TOOLS="$TOOLS" "$IMAGE" stdio 2>/dev/null \
      | jq -c 'select(.id == 2) | .result.tools'
)
[[ $(jq length <<<"$schemas") -eq 13 ]] || { echo "expected 13 tools from $IMAGE" >&2; exit 1; }

jq -n --argjson schemas "$schemas" --argjson orgs "$ORGS" \
      --arg image "$IMAGE" --arg knowledge "$(cat README.md specs/context-window-deploy.md)" '
def tool_name(org; name): "github_\(org | gsub("-"; "_"))_\(name)";
def call(id; name; args): {role: "assistant", content: "",
    tool_calls: [{id: id, type: "function", function: {name: name, arguments: (args | tojson)}}]};
{
  schema: 1,
  description: "A large tool-using request: \($image) tools (13 per org, 3 orgs), a project system prompt and retrieved knowledge. Generated by tests/fixtures/make-big-session.sh; do not hand-edit.",
  why_recorded: "Same replay rule as agent-session.json: history grows with the recorded messages only, so the prompt prefix is identical on every run.",
  system: ("You are an assistant working with the Boatload team. Its Jira project is BOAT. Its code lives in cloudwalksolutions/boatload-app and boatload-llc/boatload.\nPrefer a tool over your knowledge for current state, and cite the repo, file or pull request.\n\nKnowledge:\n" + $knowledge),
  tools: [$orgs[] as $org | $schemas[] |
    {type: "function", function: {name: tool_name($org; .name),
                                    description: "[\($org)] \(.description)",
                                    parameters: .inputSchema}}],
  turns: [
    {id: "t1-search-prs", user: "Which open pull requests in boatload-llc/boatload touch the API? Look it up.",
     expect: "tool_call",
     replay_assistant: call("call_t1"; tool_name("boatload-llc"; "search_pull_requests"); {query: "repo:boatload-llc/boatload is:pr is:open api"}),
     replay_tool: {role: "tool", tool_call_id: "call_t1",
                   content: ({total_count: 2, items: [{number: 436, title: "Retry agent calls on 5xx", state: "open"},
                                                       {number: 441, title: "Paginate the boats API", state: "open"}]} | tojson)}},
    {id: "t2-summary", user: "Summarise those in two sentences.", expect: "content",
     replay_assistant: {role: "assistant", content: "Two open pull requests touch the API: #436 retries agent calls on server errors, and #441 paginates the boats endpoint."}},
    {id: "t3-search-code", user: "Find where the agent sets its default model in boatload-llc/boatload.",
     expect: "tool_call",
     replay_assistant: call("call_t3"; tool_name("boatload-llc"; "search_code"); {query: "LLAMACPP_MODEL repo:boatload-llc/boatload"}),
     replay_tool: {role: "tool", tool_call_id: "call_t3",
                   content: ({total_count: 1, items: [{path: "src/api/src/pkg/agents/config.go", repository: "boatload-llc/boatload"}]} | tojson)}},
    {id: "t4-final", user: "Which file should I change, and what would I change it to for qwen3.6-35b-a3b?", expect: "content",
     replay_assistant: {role: "assistant", content: "Change the LLAMACPP_MODEL default in src/api/src/pkg/agents/config.go to qwen3.6-35b-a3b."}}
  ]
}' > "$OUT"

echo "wrote $OUT: $(jq '.tools | length' "$OUT") tools, $(wc -c < "$OUT") bytes"
